-- Associate the six existing archive captions with permanent picture assets.
-- Prompts used for the five generated pictures are retained alongside their paths.
alter table public.captions add column image_path text;
alter table public.captions add column image_prompt text;
alter table public.captions add constraint captions_image_path_check check (image_path is null or image_path in ('/memes/become-ungovernable.webp','/memes/hoa-tornado.webp','/memes/airport-armor.webp','/memes/raccoon-credit.webp','/memes/waiting-skeleton.webp','/memes/police-goose.webp'));
grant select (image_path, image_prompt) on public.captions to anon, authenticated;
grant insert (image_path) on public.captions to authenticated;
update public.captions set image_path = '/memes/become-ungovernable.webp', image_prompt = null where caption_text = 'BECOME UNGOVERNABLE.' and model is null and user_id is null;
update public.captions set image_path = '/memes/hoa-tornado.webp', image_prompt = 'Use case: photorealistic-natural. Asset type: photo for a meme caption card, landscape 3:2. Primary request: a candid absurd photograph of a middle-aged man calmly pushing a lawn mower across his neatly cut suburban lawn while a huge tornado approaches in the distant background. The joke is that lawn maintenance continues despite the tornado. Show the full mower and man in the foreground and clearly visible large tornado funnel in the background, ordinary overcast storm lighting, realistic documentary snapshot texture. No text, no caption, no watermarks, no collage. This is a fictional meme image.' where caption_text = 'THE HOA DEADLINE REMAINS IN EFFECT.' and model is null and user_id is null;
update public.captions set image_path = '/memes/airport-armor.webp', image_prompt = 'Use case: photorealistic-natural. Asset type: photo for a meme caption card, landscape 3:2. Primary request: an ordinary modern airport security queue, with a person wearing a complete gleaming medieval suit of plate armor, including closed helmet and clearly visible armored boots, patiently waiting among normal travelers carrying luggage. Full-body armored person prominent, airport security conveyor and checkpoint visibly establish context. Candid deadpan realistic snapshot, fluorescent lighting. No text, no caption, no watermarks, no collage. Fictional absurd meme scene.' where caption_text = 'SHOES STAY ON.' and model is null and user_id is null;
update public.captions set image_path = '/memes/raccoon-credit.webp', image_prompt = 'Use case: photorealistic-natural. Asset type: photo for a meme caption card, landscape 3:2. Primary request: a mischievous realistic raccoon at a supermarket self-checkout, holding a blank credit card in its small front paws right next to the card payment terminal, as if confidently attempting to pay. The raccoon''s face, black mask markings, striped tail, paws, credit card, and checkout are clear. Candid funny believable photograph, normal grocery store lighting. No humans required, no text, no card number or logos, no caption, no watermark, no collage. Fictional absurd meme scene.' where caption_text = 'GENERATIONAL WEALTH STARTS WITH ME.' and model is null and user_id is null;
update public.captions set image_path = '/memes/waiting-skeleton.webp', image_prompt = 'Use case: photorealistic-natural. Asset type: photo for a meme caption card, landscape 3:2. Primary request: a realistic anatomical skeleton sitting upright on an ordinary chair in a quiet modern doctor''s office waiting room, patiently holding a medical clipboard on its lap. Full skeleton head torso legs visible, waiting room chair row and reception window establish medical setting. Dry deadpan visual joke about waiting forever, mundane fluorescent lighting, candid realistic photography, non-gory. No text, no caption, no watermarks, no collage. Fictional meme scene.' where caption_text = 'THEY SAID THE DOCTOR WOULD BE RIGHT WITH ME.' and model is null and user_id is null;
update public.captions set image_path = '/memes/police-goose.webp', image_prompt = 'Use case: photorealistic-natural. Asset type: photo for a meme caption card, landscape 3:2. Primary request: a white goose with orange beak and feet standing triumphantly on the roof of a modern black-and-white police patrol car beside its light bar, looking self-important and in charge. A clearly recognizable police car side and roof are visible, goose large enough to see expression, street background. Candid realistic natural-light funny snapshot. No text apart from optional ordinary POLICE marking on car, no caption, no watermark, no collage. Fictional meme scene.' where caption_text = 'INTERNAL AFFAIRS.' and model is null and user_id is null;
